[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>IPL 2026 Ball-by-Ball Analytics Report</title>
<style>
  :root {
    --bg: #0d0f14;
    --surface: #161b24;
    --surface2: #1e2535;
    --border: #2a3347;
    --accent: #f97316;
    --accent2: #3b82f6;
    --accent3: #10b981;
    --accent4: #a855f7;
    --text: #e2e8f0;
    --text-muted: #94a3b8;
    --gold: #f59e0b;
    --red: #ef4444;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { background: var(--bg); color: var(--text); font-family: 'Segoe UI', system-ui, sans-serif; font-size: 14px; line-height: 1.6; }

  /* ── Layout ── */
  .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

  /* ── Header ── */
  .report-header {
    background: linear-gradient(135deg, #0d0f14 0%, #1a0a2e 50%, #0d1a2e 100%);
    border-bottom: 2px solid var(--accent);
    padding: 48px 0 36px;
    position: relative;
    overflow: hidden;
  }
  .report-header::before {
    content: '';
    position: absolute; top: 0; left: 0; right: 0; bottom: 0;
    background: radial-gradient(ellipse at 70% 50%, rgba(249,115,22,0.08) 0%, transparent 60%);
  }
  .header-inner { position: relative; }
  .header-tag { font-size: 11px; font-weight: 700; letter-spacing: 3px; color: var(--accent); text-transform: uppercase; margin-bottom: 12px; }
  .header-title { font-size: 42px; font-weight: 800; line-height: 1.1; background: linear-gradient(90deg, #fff 0%, var(--accent) 100%); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }
  .header-sub { font-size: 16px; color: var(--text-muted); margin-top: 10px; }
  .header-meta { margin-top: 20px; display: flex; gap: 24px; flex-wrap: wrap; }
  .header-meta span { font-size: 12px; color: var(--text-muted); }
  .header-meta strong { color: var(--text); }

  /* ── Section ── */
  .section { padding: 40px 0; border-bottom: 1px solid var(--border); }
  .section:last-child { border-bottom: none; }
  .section-header { display: flex; align-items: center; gap: 12px; margin-bottom: 28px; }
  .section-num { font-size: 11px; font-weight: 700; color: var(--accent); letter-spacing: 2px; background: rgba(249,115,22,0.1); border: 1px solid rgba(249,115,22,0.3); border-radius: 4px; padding: 2px 8px; }
  .section-title { font-size: 22px; font-weight: 700; color: #fff; }

  /* ── KPI Cards ── */
  .kpi-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px; }
  @media(max-width:900px){ .kpi-grid { grid-template-columns: repeat(3,1fr); } }
  .kpi-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 20px 16px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }
  .kpi-card::before {
    content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px;
  }
  .kpi-card.c1::before { background: var(--accent); }
  .kpi-card.c2::before { background: var(--accent2); }
  .kpi-card.c3::before { background: var(--accent3); }
  .kpi-card.c4::before { background: var(--gold); }
  .kpi-card.c5::before { background: var(--accent4); }
  .kpi-val { font-size: 32px; font-weight: 800; line-height: 1; margin-bottom: 6px; }
  .kpi-card.c1 .kpi-val { color: var(--accent); }
  .kpi-card.c2 .kpi-val { color: var(--accent2); }
  .kpi-card.c3 .kpi-val { color: var(--accent3); }
  .kpi-card.c4 .kpi-val { color: var(--gold); }
  .kpi-card.c5 .kpi-val { color: var(--accent4); }
  .kpi-label { font-size: 11px; color: var(--text-muted); font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px; }
  .kpi-desc { font-size: 10px; color: var(--text-muted); margin-top: 6px; }

  /* ── Stat summary grid ── */
  .stat-row { display: flex; gap: 16px; flex-wrap: wrap; margin-bottom: 28px; }
  .stat-pill { background: var(--surface2); border: 1px solid var(--border); border-radius: 8px; padding: 10px 16px; font-size: 13px; }
  .stat-pill strong { color: var(--accent); }

  /* ── Tables ── */
  .table-wrap { overflow-x: auto; border-radius: 10px; border: 1px solid var(--border); }
  table { width: 100%; border-collapse: collapse; font-size: 13px; }
  thead tr { background: var(--surface2); }
  th { padding: 10px 14px; text-align: left; font-size: 11px; font-weight: 700; letter-spacing: 0.5px; color: var(--text-muted); text-transform: uppercase; border-bottom: 1px solid var(--border); white-space: nowrap; }
  td { padding: 9px 14px; border-bottom: 1px solid var(--border); color: var(--text); }
  tbody tr:last-child td { border-bottom: none; }
  tbody tr:nth-child(odd) { background: rgba(255,255,255,0.015); }
  tbody tr:hover { background: rgba(255,255,255,0.04); }
  .rank { color: var(--text-muted); font-size: 12px; }
  .highlight { color: var(--accent); font-weight: 700; }
  .green { color: var(--accent3); font-weight: 600; }
  .blue { color: var(--accent2); font-weight: 600; }
  .gold { color: var(--gold); font-weight: 600; }
  .red-val { color: var(--red); font-weight: 600; }

  /* ── Charts ── */
  .chart-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-top: 24px; }
  @media(max-width:768px){ .chart-grid { grid-template-columns: 1fr; } }
  .chart-box { background: var(--surface); border: 1px solid var(--border); border-radius: 12px; padding: 20px; }
  .chart-title { font-size: 13px; font-weight: 700; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 16px; }
  svg { width: 100%; overflow: visible; }

  /* ── Bar charts ── */
  .bar-label { font-size: 11px; fill: var(--text-muted); }
  .bar-value { font-size: 11px; fill: var(--text); font-weight: 600; }
  .axis-line { stroke: var(--border); stroke-width: 1; }

  /* ── Phase cards ── */
  .phase-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 16px; }
  .phase-card { background: var(--surface); border: 1px solid var(--border); border-radius: 12px; padding: 18px; }
  .phase-name { font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 12px; }
  .phase-card.pp .phase-name { color: var(--accent2); }
  .phase-card.mid .phase-name { color: var(--accent3); }
  .phase-card.death .phase-name { color: var(--accent); }
  .phase-stat { display: flex; justify-content: space-between; padding: 5px 0; border-bottom: 1px solid var(--border); font-size: 12px; }
  .phase-stat:last-child { border-bottom: none; }
  .phase-stat-val { font-weight: 700; color: #fff; }

  /* ── Venue badges ── */
  .venue-name { max-width: 220px; white-space: normal; line-height: 1.3; font-size: 12px; }

  /* ── Two column layout ── */
  .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
  @media(max-width:768px){ .two-col { grid-template-columns: 1fr; } }

  /* ── Footer ── */
  .report-footer { background: var(--surface); border-top: 1px solid var(--border); padding: 24px 0; text-align: center; }
  .report-footer p { font-size: 12px; color: var(--text-muted); }

  /* ── Donut SVG ── */
  .donut-text { font-size: 11px; fill: var(--text-muted); }
  .donut-pct { font-size: 14px; font-weight: 700; fill: #fff; }

  /* ── Heatmap ── */
  .heatmap-cell { rx: 3; ry: 3; }
</style>
</head>
